clear;
clc;
close all;

%% Step 1: Create time vector

% Label: time in minutes
t = 0:2:20;

%% Step 2: Create temperature vector

% Label: temperature in degrees Celsius
T = [90 82 75 69 64 59 55 52 49 47 45];

%% Step 3: Plot temperature vs time

figure; %[output:695d44e0]
plot(t, T, 'LineWidth', 2); %[output:695d44e0]
grid on; %[output:695d44e0]

xlabel('Time (minutes)'); %[output:695d44e0]
ylabel('Temperature (Celsius)'); %[output:695d44e0]
title('Cooling Curve: Temperature vs Time'); %[output:695d44e0]

%% Step 4: Estimate rate of change using finite differences

% Label: change in temperature divided by change in time
rateChange = diff(T) ./ diff(t);

% Label: time values for rate of change
tRate = t(1:end-1);

figure; %[output:1226e293]
plot(tRate, rateChange, 'LineWidth', 2); %[output:1226e293]
grid on; %[output:1226e293]

xlabel('Time (minutes)'); %[output:1226e293]
ylabel('Rate of Change (Celsius per minute)'); %[output:1226e293]
title('Cooling Rate vs Time'); %[output:1226e293]

%% Step 5: Estimate total thermal exposure using area

% Label: area under T(t)
thermalExposure = trapz(t, T);

%% Display results

disp("Rate of change values:"); %[output:948b5834]
disp(rateChange); %[output:6b9bedc3]

disp("Total thermal exposure:"); %[output:4e058204]
disp(thermalExposure); %[output:7b73d07c]

disp("Interpretation:"); %[output:69368e56]
disp("The temperature decreases over time, which means the object is cooling."); %[output:56c8bab7]
disp("The rate of change is negative because temperature is going down."); %[output:302270b4]
disp("The total thermal exposure represents the accumulated temperature over the full time period."); %[output:1b74c6a5]

